source("00_helpers.R")
n <- jme$nodes; r <- jme$refs
w <- wos$nodes; wr <- wos$refs
small <- n[n$year < 1985, ]; rs <- r[r$source_id %in% small$source_id, ]
run("no method", build_network(small, rs, "source_id", "target_id"))
run("method typo", build_network(small, rs, "source_id", "target_id", method = "cosine"))
run("method coupling_angle (old value)", build_network(small, rs, "source_id", "target_id", method = "coupling_angle"))
run("source_id typo", build_network(small, rs, "sourceid", "target_id", method = "angle"))
run("target_id missing in refs", build_network(small, rs, "source_id", "cited", method = "angle"))
run("unquoted column (NSE)", build_network(small, rs, source_id, target_id, method = "angle"))
run("nodes = refs swapped", build_network(rs, small, "source_id", "target_id", method = "angle"))
run("nodes duplicated", build_network(rbind(small, small[1:3,]), rs, "source_id", "target_id", method = "angle"))
run("refs with duplicated pairs", { g <- build_network(small, rbind(rs, rs), "source_id", "target_id", method = "angle"); g0 <- build_network(small, rs, "source_id", "target_id", method = "angle", verbose = FALSE); cat("  same weights:", isTRUE(all.equal(sort(igraph::E(g)$weight), sort(igraph::E(g0)$weight))), "\n"); g })
run("NA in target_id", { rr <- rs; rr$target_id[1:50] <- NA; build_network(small, rr, "source_id", "target_id", method = "angle") })
run("NA in source_id of nodes", { nn <- small; nn$source_id[1:3] <- NA; build_network(nn, rs, "source_id", "target_id", method = "angle") })
run("empty refs", build_network(small, rs[0, ], "source_id", "target_id", method = "angle"))
run("nodes without any ref in refs", build_network(small[1:5,], rs[!rs$source_id %in% small$source_id[1:5],], "source_id", "target_id", method = "angle"))
run("tibble input", build_network(tibble::as_tibble(small), tibble::as_tibble(rs), "source_id", "target_id", method = "angle"))
run("data.table input not modified", { dn <- as.data.table(small); dr <- as.data.table(rs); before <- copy(dr); build_network(dn, dr, "source_id", "target_id", method = "angle"); cat("  unchanged:", identical(before, dr), "\n") })
run("factor ids", { ff <- small; ff$source_id <- factor(ff$source_id); fr <- rs; fr$source_id <- factor(fr$source_id); fr$target_id <- factor(fr$target_id); build_network(ff, fr, "source_id", "target_id", method = "angle") })
run("WoS integer ids", { g <- build_network(w[w$year == 1990,], wr, "source_id", "new_id", method = "angle"); cat(" ", desc(g), class(tidygraph::as_tibble(g)$source_id), "\n"); g })
run("WoS item_id with 0 = unmatched", { g <- build_network(w[w$year == 1990,], wr, "source_id", "item_id", method = "angle"); cat(" ", desc(g), "\n"); g })
run("alpha missing for sdsm", build_network(small, rs, "source_id", "target_id", method = "sdsm"))
run("edges_threshold 0", build_network(small, rs, "source_id", "target_id", method = "angle", edges_threshold = 0))
run("edges_threshold too high", build_network(small, rs, "source_id", "target_id", method = "angle", edges_threshold = 500))
run("edges_threshold = '2' (string)", build_network(small, rs, "source_id", "target_id", method = "angle", edges_threshold = "2"))
run("keep_singleton TRUE", { g <- build_network(small, rs, "source_id", "target_id", method = "angle", keep_singleton = TRUE, verbose = FALSE); cat(" ", desc(g), "\n") })
run("filter_components with nb_components", build_network(small, rs, "source_id", "target_id", method = "angle", filter_components = TRUE, nb_components = 2))
run("misspelt filter arg", build_network(small, rs, "source_id", "target_id", method = "angle", filter_components = TRUE, nb_component = 2))
run("dynamic: no time", build_dynamic_networks(n, r, "source_id", "target_id", method = "angle"))
run("dynamic: time_variable missing column", build_dynamic_networks(n, r, "source_id", "target_id", method = "angle", time_variable = "annee", time_window = 5))
run("dynamic: character years", { nn <- n; nn$year <- as.character(nn$year); g <- build_dynamic_networks(nn, r, "source_id", "target_id", method = "angle", time_variable = "year", time_window = 10); cat(" ", names(g), "\n") })
run("dynamic: time_window larger than period", { g <- build_dynamic_networks(n, r, "source_id", "target_id", method = "angle", time_variable = "year", time_window = 100); cat(" ", names(g), "\n") })
run("dynamic: time_window 0", build_dynamic_networks(n, r, "source_id", "target_id", method = "angle", time_variable = "year", time_window = 0))
run("dynamic: window_step > window", { g <- build_dynamic_networks(n, r, "source_id", "target_id", method = "angle", time_variable = "year", time_window = 3, window_step = 5); cat(" ", names(g), "\n") })
run("dynamic: time_unit on years", build_dynamic_networks(n, r, "source_id", "target_id", method = "angle", time_variable = "year", time_window = 5, time_unit = "month"))
run("dynamic: real Scopus odd dates (1892, 2026)", { g <- build_dynamic_networks(s30$nodes, s30$refs, "source_id", "target_id", method = "angle", time_variable = "year", time_window = 10, edges_threshold = 2); cat(" ", paste(names(g), sapply(g, igraph::vcount), collapse=" "), "\n") })
run("dynamic: overlapping_window", build_dynamic_networks(n, r, "source_id", "target_id", method = "angle", time_variable = "year", time_window = 5, overlapping_window = TRUE))
